declare
  invite_row public.team_invites%rowtype;
  member_row public.team_memberships%rowtype;
  current_email text := lower(auth.jwt() ->> 'email');
  current_name text := coalesce(
    auth.jwt() -> 'user_metadata' ->> 'display_name',
    auth.jwt() -> 'user_metadata' ->> 'full_name',
    auth.jwt() -> 'user_metadata' ->> 'name',
    split_part(current_email, '@', 1)
  );
begin
  if auth.uid() is null then
    raise exception 'Sign in before accepting a team invite';
  end if;

  if coalesce(p_token_hash, '') = '' then
    raise exception 'Invite token is required';
  end if;

  select *
  into invite_row
  from public.team_invites
  where token_hash = p_token_hash
  for update;

  if not found then
    raise exception 'Invalid team invite';
  end if;

  if invite_row.status <> 'pending' then
    raise exception 'Team invite is not pending';
  end if;

  if invite_row.expires_at <= now() then
    update public.team_invites
    set status = 'expired'
    where id = invite_row.id;
    raise exception 'Team invite has expired';
  end if;

  if lower(invite_row.email) <> current_email then
    raise exception 'This invite belongs to a different email address';
  end if;

  update public.team_invites
  set status = 'accepted',
      accepted_by = auth.uid(),
      accepted_at = now()
  where id = invite_row.id;

  update public.team_memberships
  set user_id = auth.uid(),
      email = invite_row.email,
      display_name = coalesce(display_name, current_name),
      role = invite_row.role,
      role_label = invite_row.role_label,
      status = 'active'
  where team_memberships.team_id = invite_row.team_id
    and lower(team_memberships.email) = lower(invite_row.email)
  returning * into member_row;

  if member_row.id is null then
    insert into public.team_memberships (
      team_id,
      user_id,
      email,
      display_name,
      role,
      role_label,
      status,
      created_by
    )
    values (
      invite_row.team_id,
      auth.uid(),
      invite_row.email,
      current_name,
      invite_row.role,
      invite_row.role_label,
      'active',
      invite_row.created_by
    )
    returning * into member_row;
  end if;

  return query
  select invite_row.team_id, member_row.id, member_row.role, member_row.role_label;
end;

declare
  actor_id uuid := auth.uid();
  legacy_row public.test_ids%rowtype;
  clean_reason text := btrim(coalesce(p_reason, ''));
  supplied_count integer := coalesce(cardinality(p_ordered_question_ids), 0);
  inserted_count integer;
begin
  if not public.is_admin() or actor_id is null then
    raise exception 'Administrator or Owner access is required for legacy Test ID backfill.';
  end if;

  if length(clean_reason) < 10 then
    raise exception 'A backfill reason of at least 10 characters is required.';
  end if;

  select *
  into legacy_row
  from public.test_ids
  where id = upper(btrim(p_legacy_test_id))
  for update;

  if not found then
    raise exception 'Legacy Test ID was not found.';
  end if;

  if legacy_row.generation_status <> 'Legacy' then
    raise exception 'Only unresolved Legacy Test IDs can be backfilled.';
  end if;

  if supplied_count <> legacy_row.question_count then
    raise exception 'Ordered question count must equal the original Test ID question count.';
  end if;

  if supplied_count < 1 or supplied_count > 250 then
    raise exception 'Legacy membership must contain between 1 and 250 questions.';
  end if;

  if (
    select count(distinct question_id)
    from unnest(p_ordered_question_ids) question_id
  ) <> supplied_count then
    raise exception 'Legacy membership cannot contain duplicate question IDs.';
  end if;

  if (
    select count(*)
    from public.questions question
    where question.id = any(p_ordered_question_ids)
  ) <> supplied_count then
    raise exception 'Every legacy membership question must exist in the repository.';
  end if;

  insert into public.test_definition_questions (
    test_definition_id,
    question_id,
    position,
    stratum_id,
    content_hash,
    question_updated_at
  )
  select
    legacy_row.definition_id,
    question.id,
    ordered.ordinality::integer,
    'legacy-backfill',
    coalesce(
      question.question_hash,
      encode(
        extensions.digest(
          convert_to(
            jsonb_build_object(
              'question_text', question.question_text,
              'options', question.options,
              'correct_option_id', question.correct_option_id,
              'explanation', question.explanation,
              'difficulty', question.difficulty,
              'tags', question.tags
            )::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      )
    ),
    question.updated_at
  from unnest(p_ordered_question_ids) with ordinality ordered(question_id, ordinality)
  join public.questions question on question.id = ordered.question_id
  order by ordered.ordinality;

  get diagnostics inserted_count = row_count;

  update public.test_ids
  set generation_status = 'Ready',
      selected_question_count = inserted_count,
      algorithm_version = 'legacy-membership-v1',
      eligibility_rule_version = 'legacy-current-snapshot-v1',
      canonical_seed = coalesce(canonical_seed, id),
      content_policy = 'current_with_warning',
      completed_at = now(),
      generation_metadata = generation_metadata || jsonb_build_object(
        'legacy_backfilled_at', now(),
        'legacy_backfilled_by', actor_id,
        'legacy_backfill_reason', clean_reason
      )
  where definition_id = legacy_row.definition_id;

  insert into public.legacy_test_id_resolutions (
    legacy_test_id,
    resolution_status,
    reason,
    resolved_by
  )
  values (
    legacy_row.id,
    'Backfilled',
    clean_reason,
    actor_id
  );

  insert into public.admin_audit_logs (
    actor_user_id,
    actor_email,
    action,
    resource_type,
    resource_id,
    reason,
    metadata
  )
  values (
    actor_id,
    (select email from auth.users where id = actor_id),
    'Legacy Test ID backfilled',
    'test_id',
    legacy_row.id,
    clean_reason,
    jsonb_build_object('question_count', inserted_count)
  );

  return inserted_count;
end;

declare
  previous_role text;
begin
  perform private.assert_server_context();
  if p_target_user_id is null then
    raise exception 'Target user is required.';
  end if;

  if exists (
    select 1
    from public.profiles
    where role = 'owner'
      and owner_privileges_suspended = false
      and (
        suspended_until is null
        or suspended_until < now()
      )
  ) then
    raise exception 'Initial owner bootstrap is only available before any active owner exists.';
  end if;

  select role
  into previous_role
  from public.profiles
  where user_id = p_target_user_id;

  insert into public.profiles(user_id, role, account_tier)
  values (p_target_user_id, 'owner', 'premium')
  on conflict (user_id) do update
  set role = 'owner',
      account_tier = greatest(public.profiles.account_tier, excluded.account_tier),
      updated_at = now();

  insert into public.admin_audit_logs(
    actor_user_id,
    action,
    resource_type,
    resource_id,
    reason,
    metadata
  )
  values (
    null,
    'Initial owner bootstrapped',
    'profile',
    p_target_user_id::text,
    nullif(trim(coalesce(p_reason, '')), ''),
    jsonb_build_object(
      'target_user_id', p_target_user_id,
      'previous_role', previous_role,
      'new_role', 'owner',
      'trusted_bootstrap', true
    )
  );
end;

declare
  blueprint_row public.blueprint_versions%rowtype;
  raw_stratum jsonb;
  canonical_strata jsonb := '[]'::jsonb;
  stratum_id text;
  stratum_count integer;
  stratum_priority integer;
  partitions text[];
  indicators text[];
  question_types text[];
  difficulties text[];
  tags text[];
  excluded_tags text[];
  total_count integer := 0;
  ordinal integer := 0;
begin
  select *
  into blueprint_row
  from public.blueprint_versions
  where id = p_blueprint_id;

  if not found then
    raise exception 'Blueprint was not found.';
  end if;

  if blueprint_row.status <> 'Active' then
    raise exception 'Only active blueprint versions can generate tests.';
  end if;

  if p_expected_version is not null and blueprint_row.version <> p_expected_version then
    raise exception 'Blueprint version changed. Refresh before generating.';
  end if;

  if blueprint_row.total_questions < 1 or blueprint_row.total_questions > 250 then
    raise exception 'Blueprint question count must be between 1 and 250.';
  end if;

  if jsonb_typeof(blueprint_row.distribution) <> 'object'
     or jsonb_typeof(blueprint_row.distribution -> 'strata') <> 'array'
     or jsonb_array_length(blueprint_row.distribution -> 'strata') = 0 then
    raise exception 'Blueprint distribution must contain a non-empty strata array.';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(blueprint_row.distribution) key
    where key not in ('schema_version', 'strata')
  ) then
    raise exception 'Blueprint distribution contains an unknown top-level field.';
  end if;

  if coalesce((blueprint_row.distribution ->> 'schema_version')::integer, 1) <> 1 then
    raise exception 'Unsupported blueprint schema version.';
  end if;

  for raw_stratum in
    select value
    from jsonb_array_elements(blueprint_row.distribution -> 'strata')
  loop
    ordinal := ordinal + 1;

    if jsonb_typeof(raw_stratum) <> 'object' then
      raise exception 'Every blueprint stratum must be an object.';
    end if;

    if exists (
      select 1
      from jsonb_object_keys(raw_stratum) key
      where key not in (
        'id', 'priority', 'count', 'partition_keys', 'performance_indicators',
        'question_types', 'difficulties', 'tags', 'excluded_tags'
      )
    ) then
      raise exception 'Blueprint stratum contains an unknown field.';
    end if;

    stratum_id := btrim(coalesce(raw_stratum ->> 'id', ''));
    if stratum_id !~ '^[a-z0-9][a-z0-9_-]{0,63}$' then
      raise exception 'Blueprint stratum id must use 1-64 lowercase letters, numbers, underscores, or hyphens.';
    end if;

    if exists (
      select 1
      from jsonb_array_elements(canonical_strata) existing
      where existing ->> 'id' = stratum_id
    ) then
      raise exception 'Blueprint stratum ids must be unique.';
    end if;

    if jsonb_typeof(raw_stratum -> 'count') <> 'number'
       or (raw_stratum ->> 'count') !~ '^[0-9]+$' then
      raise exception 'Blueprint stratum % count must be a non-negative integer.', stratum_id;
    end if;
    stratum_count := (raw_stratum ->> 'count')::integer;
    if stratum_count < 1 or stratum_count > 250 then
      raise exception 'Blueprint stratum % count must be between 1 and 250.', stratum_id;
    end if;

    if raw_stratum ? 'priority' then
      if jsonb_typeof(raw_stratum -> 'priority') <> 'number'
         or (raw_stratum ->> 'priority') !~ '^[0-9]+$' then
        raise exception 'Blueprint stratum % priority must be a non-negative integer.', stratum_id;
      end if;
      stratum_priority := (raw_stratum ->> 'priority')::integer;
    else
      stratum_priority := ordinal;
    end if;

    if stratum_priority > 10000 then
      raise exception 'Blueprint stratum priority cannot exceed 10000.';
    end if;

    partitions := public.test_blueprint_text_array(raw_stratum -> 'partition_keys', 'partition_keys');
    if cardinality(partitions) = 0 then
      partitions := array[blueprint_row.category];
    end if;
    if exists (select 1 from unnest(partitions) value where value <> blueprint_row.category) then
      raise exception 'Every stratum partition key must match the blueprint category.';
    end if;

    indicators := public.test_blueprint_text_array(raw_stratum -> 'performance_indicators', 'performance_indicators');
    question_types := public.normalize_test_question_types(
      public.test_blueprint_text_array(raw_stratum -> 'question_types', 'question_types')
    );
    difficulties := public.normalize_test_difficulties(
      public.test_blueprint_text_array(raw_stratum -> 'difficulties', 'difficulties')
    );
    tags := public.test_blueprint_text_array(raw_stratum -> 'tags', 'tags');
    excluded_tags := public.test_blueprint_text_array(raw_stratum -> 'excluded_tags', 'excluded_tags');

    if tags && excluded_tags then
      raise exception 'Blueprint stratum % requires and excludes the same tag.', stratum_id;
    end if;

    total_count := total_count + stratum_count;
    canonical_strata := canonical_strata || jsonb_build_array(
      jsonb_build_object(
        'id', stratum_id,
        'priority', stratum_priority,
        'count', stratum_count,
        'partition_keys', to_jsonb(partitions),
        'performance_indicators', to_jsonb(indicators),
        'question_types', to_jsonb(question_types),
        'difficulties', to_jsonb(difficulties),
        'tags', to_jsonb(tags),
        'excluded_tags', to_jsonb(excluded_tags)
      )
    );
  end loop;

  if total_count <> blueprint_row.total_questions then
    raise exception 'Blueprint stratum counts (%) must equal total_questions (%).', total_count, blueprint_row.total_questions;
  end if;

  return jsonb_build_object(
    'schema_version', 1,
    'blueprint_id', blueprint_row.id,
    'blueprint_name', blueprint_row.blueprint_name,
    'blueprint_version', blueprint_row.version,
    'cluster', blueprint_row.cluster,
    'level', blueprint_row.level,
    'category', blueprint_row.category,
    'total_questions', blueprint_row.total_questions,
    'tag_semantics', 'AND',
    'allocation_policy', 'most_constrained_first_v1',
    'strata', canonical_strata
  );
end;

declare
  actor_id uuid := auth.uid();
  vote_row public.governance_votes%rowtype;
  approve_count integer;
  normalized_decision text := initcap(lower(trim(coalesce(p_decision, ''))));
begin
  if not public.is_eligible_owner(actor_id) then
    raise exception 'Eligible owner access is required to vote.';
  end if;

  if normalized_decision not in ('Approve', 'Reject') then
    raise exception 'Owner-removal vote decision must be Approve or Reject.';
  end if;

  select *
  into vote_row
  from public.governance_votes
  where id = p_vote_id
    and vote_kind = 'owner_removal'
  for update;

  if not found then
    raise exception 'Owner-removal vote was not found.';
  end if;

  if vote_row.status <> 'Open' then
    raise exception 'Owner-removal vote is no longer open.';
  end if;

  if vote_row.expires_at <= now() then
    update public.governance_votes
    set status = 'Expired',
        resolved_at = now()
    where id = p_vote_id;
    raise exception 'Owner-removal vote has expired.';
  end if;

  if vote_row.target_user_id = actor_id then
    raise exception 'Target owners cannot vote on their own removal.';
  end if;

  insert into public.governance_ballots(vote_id, owner_user_id, decision, withdrawn_at)
  values (p_vote_id, actor_id, normalized_decision, null)
  on conflict (vote_id, owner_user_id) do update
  set decision = excluded.decision,
      withdrawn_at = null,
      updated_at = now();

  perform public.write_admin_audit(
    'Owner removal ballot cast',
    'governance_vote',
    p_vote_id::text,
    vote_row.reason,
    jsonb_build_object(
      'acting_user_id', actor_id,
      'target_user_id', vote_row.target_user_id,
      'decision', normalized_decision
    )
  );

  select count(*)::integer
  into approve_count
  from public.governance_ballots
  where vote_id = p_vote_id
    and decision = 'Approve'
    and withdrawn_at is null;

  if approve_count >= vote_row.required_approvals then
    update public.profiles
    set role = 'admin',
        owner_state = 'unavailable',
        owner_privileges_suspended = true,
        owner_state_updated_at = now(),
        updated_at = now()
    where user_id = vote_row.target_user_id
      and role = 'owner';

    update public.governance_votes
    set status = 'Executed',
        resolved_at = now(),
        executed_at = now(),
        metadata = metadata || jsonb_build_object(
          'executed_by_vote_count', approve_count,
          'executed_at', now()
        )
    where id = p_vote_id;

    perform public.write_admin_audit(
      'Owner removed',
      'profile',
      vote_row.target_user_id::text,
      vote_row.reason,
      jsonb_build_object(
        'acting_user_id', actor_id,
        'target_user_id', vote_row.target_user_id,
        'governance_vote_id', p_vote_id,
        'approval_count', approve_count,
        'previous_role', 'owner',
        'new_role', 'admin',
        'new_owner_state', 'unavailable'
      )
    );

    return 'Executed';
  end if;

  return 'Recorded';
end;

declare seconds integer;
begin
  select timer_seconds into seconds from public.test_sessions where id = new.session_id;
  if seconds is not null then new.active_duration_seconds := least(new.active_duration_seconds, seconds); end if;
  return new;
end;

declare
  actor_id uuid := auth.uid();
  actor_role text := public.current_user_role();
  report_row public.question_reports%rowtype;
  question_row public.questions%rowtype;
  updated_question public.questions%rowtype;
  version_id uuid;
  next_version integer;
  clean_question text := trim(coalesce(p_question_text, ''));
  clean_answer text := upper(trim(coalesce(p_correct_option_id, '')));
  clean_explanation text := trim(coalesce(p_explanation, ''));
  clean_indicator text := trim(coalesce(p_performance_indicator, ''));
  clean_partition text := trim(coalesce(p_partition_key, ''));
  clean_type text := upper(trim(coalesce(p_question_type, '')));
  clean_difficulty text := upper(trim(coalesce(p_difficulty, '')));
  clean_reason text := trim(coalesce(p_reason, ''));
  clean_resolution text := trim(coalesce(p_resolution_message, ''));
  clean_key text := trim(coalesce(p_idempotency_key, ''));
  stored_type text;
  stored_difficulty text;
  before_snapshot jsonb;
  after_snapshot jsonb;
begin
  if not public.is_admin() or actor_id is null then
    raise exception 'Administrator or Owner access is required.';
  end if;
  if length(clean_key) < 1 or length(clean_key) > 128 then raise exception 'A valid idempotency key is required.'; end if;
  if length(clean_reason) < 5 or length(clean_reason) > 1000 then raise exception 'Correction reason must contain between 5 and 1000 characters.'; end if;
  if length(clean_resolution) < 5 or length(clean_resolution) > 1000 then raise exception 'Resolution message must contain between 5 and 1000 characters.'; end if;
  if length(clean_question) < 5 or length(clean_question) > 5000 then raise exception 'Question text must contain between 5 and 5000 characters.'; end if;
  if length(clean_explanation) < 5 or length(clean_explanation) > 5000 then raise exception 'Explanation must contain between 5 and 5000 characters.'; end if;
  if length(clean_indicator) < 1 or length(clean_indicator) > 200 then raise exception 'A valid performance indicator is required.'; end if;
  if clean_partition not in (
    'Business Administration Core', 'Marketing', 'Finance',
    'Business Management and Administration', 'Hospitality and Tourism', 'Entrepreneurship'
  ) then raise exception 'Invalid partition key.'; end if;
  if clean_type not in ('S','D','F','A') then raise exception 'Question type must be S, D, F, or A.'; end if;
  if clean_difficulty not in ('E','M','H') then raise exception 'Difficulty must be E, M, or H.'; end if;
  if clean_answer not in ('A','B','C','D') then raise exception 'Correct option must be A, B, C, or D.'; end if;
  if p_options is null or jsonb_typeof(p_options) <> 'array' or jsonb_array_length(p_options) <> 4 then
    raise exception 'Exactly four answer options are required.';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_options) with ordinality option(value, position)
    where case
      when jsonb_typeof(option.value) = 'string' then length(trim(option.value #>> '{}')) = 0
      when jsonb_typeof(option.value) = 'object' then
        length(trim(coalesce(option.value ->> 'text', ''))) = 0
        or upper(coalesce(option.value ->> 'id', '')) <> substr('ABCD', option.position::integer, 1)
      else true
    end
  ) then raise exception 'Every answer option must have a non-empty value and canonical position.'; end if;
  if p_tags is null or cardinality(p_tags) < 1 or cardinality(p_tags) > 20
    or exists(select 1 from unnest(p_tags) tag where length(trim(tag)) < 1 or length(trim(tag)) > 100)
  then raise exception 'Between 1 and 20 valid topic tags are required.'; end if;

  select report.* into report_row
  from public.question_reports report where report.id = p_report_id for update;
  if not found then raise exception 'Question report was not found.'; end if;
  if report_row.status in ('resolved','rejected','duplicate') then
    if report_row.status = 'resolved' and report_row.resolution_idempotency_key = clean_key
      and report_row.correction_version_id is not null then
      select * into updated_question from public.questions where id = report_row.question_id;
      return query select report_row.id, report_row.status, report_row.version,
        updated_question.id, updated_question.updated_at, report_row.correction_version_id;
      return;
    end if;
    raise exception 'Finalized reports cannot be changed.';
  end if;
  if report_row.version <> p_expected_report_version then raise exception 'Report version conflict. Reload before retrying.'; end if;

  select question.* into question_row
  from public.questions question where question.id = report_row.question_id for update;
  if not found then raise exception 'Reported question was not found.'; end if;
  if question_row.updated_at <> p_expected_question_updated_at then raise exception 'Question version conflict. Reload before retrying.'; end if;

  stored_type := case clean_type when 'S' then 'Scenario' when 'D' then 'Definition'
    when 'F' then 'Fill In The Blank' else 'All Except' end;
  stored_difficulty := case clean_difficulty when 'E' then 'Easy' when 'M' then 'Medium' else 'Hard' end;

  before_snapshot := jsonb_build_object(
    'question_text', question_row.question_text, 'options', question_row.options,
    'correct_option_id', question_row.correct_option_id, 'explanation', question_row.explanation,
    'performance_indicator', question_row.performance_indicator,
    'partition_key', question_row.partition_key, 'question_type', question_row.question_type,
    'difficulty', question_row.difficulty, 'tags', question_row.tags,
    'lifecycle_state', question_row.lifecycle_state, 'updated_at', question_row.updated_at
  );
  after_snapshot := jsonb_build_object(
    'question_text', clean_question, 'options', p_options,
    'correct_option_id', clean_answer, 'explanation', clean_explanation,
    'performance_indicator', clean_indicator, 'partition_key', clean_partition,
    'question_type', stored_type, 'difficulty', stored_difficulty,
    'tags', array(select distinct trim(tag) from unnest(p_tags) tag order by trim(tag)),
    'lifecycle_state', question_row.lifecycle_state
  );

  select coalesce(max(version.version_number), 0) + 1 into next_version
  from public.question_versions version
  where version.question_id = question_row.id;

  insert into public.question_versions(
    question_id, version_number, snapshot, previous_snapshot,
    change_reason, created_by, report_id
  ) values (
    question_row.id, next_version, after_snapshot, before_snapshot,
    clean_reason, actor_id, report_row.id
  ) returning id into version_id;

  update public.questions
  set question_text = clean_question,
      options = p_options,
      correct_option_id = clean_answer,
      explanation = clean_explanation,
      performance_indicator = clean_indicator,
      partition_key = clean_partition,
      question_type = stored_type,
      difficulty = stored_difficulty,
      tags = array(select distinct trim(tag) from unnest(p_tags) tag order by trim(tag)),
      question_hash = encode(extensions.digest(convert_to(after_snapshot::text, 'UTF8'), 'sha256'), 'hex')
  where id = question_row.id
  returning * into updated_question;

  update public.question_reports
  set status = 'resolved', resolution_category = 'corrected',
      resolution_message = clean_resolution, resolved_at = now(), reviewed_by = actor_id,
      reviewed_at = now(), correction_version_id = version_id,
      resolution_idempotency_key = clean_key, version = version + 1
  where id = report_row.id
  returning * into report_row;

  insert into public.admin_audit_logs(
    actor_user_id, actor_email, actor_role, action, resource_type, resource_id,
    report_id, reason, correlation_id, previous_values, new_values, metadata
  ) values (
    actor_id, (select email from auth.users where id = actor_id), actor_role,
    'question.corrected', 'question', question_row.id::text, report_row.id,
    clean_reason, clean_key, before_snapshot, after_snapshot,
    jsonb_build_object('question_version_id', version_id, 'report_status', 'resolved')
  );

  return query select report_row.id, report_row.status, report_row.version,
    updated_question.id, updated_question.updated_at, version_id;
end;

declare elapsed integer;
begin
  if old.timer_seconds is null then return new; end if;
  elapsed := old.accumulated_active_seconds + case when old.status = 'in_progress'
    then greatest(0, extract(epoch from (now() - old.active_period_started_at))::integer) else 0 end;
  if elapsed >= old.timer_seconds and new.status <> 'submitted' then
    raise exception 'Time has expired. Submit this test to view your results.';
  end if;
  if new.status = 'submitted' then
    new.accumulated_active_seconds := least(new.accumulated_active_seconds, old.timer_seconds);
  end if;
  return new;
end;

declare s public.test_sessions%rowtype;
begin
  select * into s from public.test_sessions where id = new.session_id for update;
  if s.timer_seconds is not null and s.accumulated_active_seconds +
    greatest(0, extract(epoch from (now() - s.active_period_started_at))::integer) >= s.timer_seconds then
    raise exception 'Time has expired. Submit this test to view your results.';
  end if;
  return new;
end;

declare
  expired_count integer;
begin
  if auth.role() <> 'service_role'
    and not public.is_owner() then
    raise exception 'Owner or service-role access is required to expire owner-removal votes.';
  end if;

  update public.governance_votes
  set status = 'Expired',
      resolved_at = now()
  where vote_kind = 'owner_removal'
    and status = 'Open'
    and expires_at <= now();

  get diagnostics expired_count = row_count;
  return expired_count;
end;

declare
  actor uuid := auth.uid();
  source jsonb;
  selected_strata jsonb;
  allowed_tags text[];
  selected_tags text[];
  difficulties text[];
  settings jsonb;
  config_hash text;
  derived_id uuid;
  generated record;
begin
  if actor is null then raise exception 'Authentication is required.'; end if;
  if p_question_count is null or p_question_count not between 1 and 250 then
    raise exception 'Question count must be between 1 and 250.';
  end if;
  if p_timer_minutes is not null and p_timer_minutes not between 1 and 999 then
    raise exception 'Timer must be between 1 and 999 minutes.';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null or length(p_idempotency_key) > 128 then
    raise exception 'A valid idempotency key is required.';
  end if;
  if not exists (select 1 from public.blueprint_versions
    where id = p_blueprint_id and practice_parent_id is null) then
    raise exception 'Select an approved blueprint template.';
  end if;
  if (coalesce(p_show_answers, false) or coalesce(p_show_explanations, false))
    and not public.has_premium_explanation_access(actor) then
    raise exception 'Study mode requires premium access.';
  end if;
  source := public.canonicalize_test_blueprint(p_blueprint_id, p_expected_version);
  difficulties := public.normalize_test_difficulties(p_difficulties);
  if cardinality(difficulties) = 0 then raise exception 'Select at least one difficulty.'; end if;
  select coalesce(array_agg(distinct tag order by tag), '{}') into allowed_tags
    from jsonb_array_elements(source->'strata') s,
    jsonb_array_elements_text(s->'tags') tag;
  select coalesce(array_agg(distinct tag order by tag), '{}') into selected_tags
    from unnest(coalesce(p_topic_tags, '{}')) tag;
  if not selected_tags <@ allowed_tags then
    raise exception 'Topic tags must belong to the selected blueprint.';
  end if;
  if cardinality(allowed_tags) > 0 and cardinality(selected_tags) = 0 then
    raise exception 'Select at least one topic.';
  end if;

  -- Topic selection chooses strata (OR across topics); each stratum retains its
  -- existing AND tag semantics and all indicator/type/exclusion constraints.
  -- Largest-remainder allocation scales approved proportions to the exact count.
  with eligible as (
    select s, (s->>'count')::numeric as weight,
      case when jsonb_array_length(s->'difficulties') = 0 then difficulties
        else array(select value from (
          select jsonb_array_elements_text(s->'difficulties') as value
          intersect select unnest(difficulties)
        ) intersection_values order by value) end as ds
    from jsonb_array_elements(source->'strata') s
    where cardinality(selected_tags) = 0
       or jsonb_array_length(s->'tags') = 0
       or array(select jsonb_array_elements_text(s->'tags')) && selected_tags
  ), weighted as (
    select *, p_question_count * weight / sum(weight) over () as quota
    from eligible where cardinality(ds) > 0
  ), ranked as (
    select *, row_number() over (order by quota - floor(quota) desc, s->>'id') as rank,
      p_question_count - sum(floor(quota)) over () as remainder from weighted
  ), allocated as (
    select s || jsonb_build_object('count', floor(quota)::integer + case when rank <= remainder then 1 else 0 end,
      'difficulties', to_jsonb(ds)) as item from ranked
  ) select jsonb_agg(item order by item->>'id') into selected_strata
    from allocated where (item->>'count')::integer > 0;
  if selected_strata is null then raise exception 'No blueprint topics match these difficulties.'; end if;
  settings := jsonb_build_object('timer_minutes', p_timer_minutes,
    'show_answers', coalesce(p_show_answers, false),
    'show_explanations', coalesce(p_show_explanations, false));
  config_hash := encode(extensions.digest(source::text || selected_strata::text || settings::text, 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(actor::text || config_hash, 0));
  select id into derived_id from public.blueprint_versions
    where practice_owner_id = actor and practice_request_hash = config_hash;
  if derived_id is null then
    derived_id := gen_random_uuid();
    insert into public.blueprint_versions(id, blueprint_name, cluster, level, category,
      version, distribution, total_questions, change_reason, created_by,
      practice_parent_id, practice_owner_id, practice_request_hash)
    values (derived_id, source->>'blueprint_name', source->>'cluster', source->>'level', source->>'category',
      'practice-' || derived_id::text,
      jsonb_build_object('schema_version', 1, 'strata', selected_strata), p_question_count,
      'Private practice configuration based on ' || (source->>'blueprint_version'), actor,
      p_blueprint_id, actor, config_hash);
  end if;
  select * into generated from public.generate_test_from_blueprint(
    derived_id, 'practice-' || derived_id::text, p_question_count, p_seed, p_idempotency_key);
  if generated.success then
    update public.test_ids set practice_settings = settings,
      blueprint_snapshot = blueprint_snapshot || jsonb_build_object('practice_source', source),
      generation_metadata = generation_metadata || jsonb_build_object('practice_settings', settings,
        'source_blueprint_id', p_blueprint_id, 'source_blueprint_version', p_expected_version)
    where id = generated.test_id;
  end if;
  return to_jsonb(generated);
end;

declare
  alphabet constant text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  random_bytes bytea := extensions.gen_random_bytes(12);
  result text := '';
  index_value integer;
begin
  for index_value in 0..11 loop
    result := result || substr(alphabet, (get_byte(random_bytes, index_value) % 36) + 1, 1);
  end loop;

  return result;
end;

