declare
  actor_id uuid := auth.uid();
  bounded_limit integer := least(greatest(coalesce(p_page_size, 20), 1), 50);
begin
  if actor_id is null then raise exception 'Authentication is required to view reports.'; end if;
  if (p_cursor_created_at is null) <> (p_cursor_id is null) then
    raise exception 'Both report cursor values are required.';
  end if;

  return query
  with page as (
    select report.*, row_number() over (order by report.created_at desc, report.id desc) page_row
    from public.question_reports report
    where report.reporter_id = actor_id
      and (p_cursor_created_at is null or (report.created_at, report.id) < (p_cursor_created_at, p_cursor_id))
    order by report.created_at desc, report.id desc
    limit bounded_limit + 1
  )
  select page.id, page.question_id, page.test_id, page.category, page.status,
    page.resolution_category, page.resolution_message, page.created_at, page.updated_at,
    exists(select 1 from page extra where extra.page_row > bounded_limit)
  from page where page.page_row <= bounded_limit
  order by page.created_at desc, page.id desc;
end;

declare s public.test_sessions%rowtype; q public.test_session_questions%rowtype;
begin
  select * into s from public.test_sessions where id = p_session_id and user_id = auth.uid();
  if not found then raise exception 'Session not found.'; end if;
  if not public.has_premium_explanation_access(auth.uid()) then raise exception 'Premium access is required.'; end if;
  if not (s.show_answers or s.show_explanations) then raise exception 'Study mode is not enabled.'; end if;
  if not exists(select 1 from public.test_session_answers where session_id = s.id and question_id = p_question_id) then
    raise exception 'Answer this question before reviewing feedback.';
  end if;
  select * into q from public.test_session_questions where session_id = s.id and question_id = p_question_id;
  return jsonb_build_object('correct_option_id', case when s.show_answers then q.correct_option_id_at_start end,
    'explanation', case when s.show_explanations then q.explanation_at_start end);
end;

declare s public.test_sessions%rowtype; elapsed integer;
begin
  select * into s from public.test_sessions where id = p_session_id and user_id = auth.uid() for update;
  if not found then raise exception 'Session not found.'; end if;
  elapsed := s.accumulated_active_seconds + case when s.status = 'in_progress'
    then greatest(0, extract(epoch from (now() - s.active_period_started_at))::integer) else 0 end;
  if s.timer_seconds is not null and elapsed >= s.timer_seconds and s.status = 'in_progress' then
    perform public.submit_test_session(s.id, s.version);
    s.status := 'submitted';
  end if;
  return jsonb_build_object('timer_seconds', s.timer_seconds, 'active_duration_seconds', elapsed,
    'status', s.status, 'show_answers', s.show_answers, 'show_explanations', s.show_explanations);
end;

begin
  if auth.uid() is null then
    raise exception 'Authentication is required to retrieve explanations.';
  end if;

  if not public.has_premium_explanation_access(auth.uid()) then
    raise exception 'Premium access is required to retrieve explanations.';
  end if;

  if not exists (
    select 1
    from public.test_ids generated
    join public.test_definition_questions membership
      on membership.test_definition_id = generated.definition_id
    where generated.id = upper(btrim(p_test_id))
      and generated.generation_status = 'Ready'
      and membership.question_id = p_question_id
  ) then
    raise exception 'Question is not part of this launchable Test ID.';
  end if;

  return query
  select question.id, question.explanation
  from public.questions question
  where question.id = p_question_id;
end;

declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then raise exception 'Authentication is required to view explanations.'; end if;
  if not public.has_premium_explanation_access(actor_id) then raise exception 'Premium access is required to retrieve explanations.'; end if;
  if not exists (
    select 1 from public.test_results result
    where result.session_id = p_session_id and result.user_id = actor_id
  ) then raise exception 'Test result was not found.'; end if;

  return query
  select item.question_id, item.explanation_snapshot
  from public.test_result_items item
  where item.session_id = p_session_id
  order by item.position;
end;

declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then raise exception 'Authentication is required to view a result.'; end if;
  if not exists (
    select 1 from public.test_results result
    where result.session_id = p_session_id and result.user_id = actor_id
  ) then raise exception 'Test result was not found.'; end if;

  return query
  select
    result.session_id, generated.id, result.total_questions,
    result.answered_questions, result.unanswered_questions,
    result.correct_answers, result.incorrect_answers, result.percentage,
    result.active_duration_seconds, result.submitted_at,
    public.has_premium_explanation_access(actor_id),
    item.position, item.question_id, item.question_type, item.question_text,
    item.options, item.difficulty, item.tags, item.selected_option_id,
    item.correct_option_id, item.is_correct
  from public.test_results result
  join public.test_ids generated on generated.definition_id = result.test_definition_id
  join public.test_result_items item on item.session_id = result.session_id
  where result.session_id = p_session_id and result.user_id = actor_id
  order by item.position;
end;

