declare
  v_candidate public.generated_question_candidates%rowtype;
  v_partition_key text;
  v_published_question_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Administrator or Owner access is required to publish generated questions.';
  end if;

  select *
  into v_candidate
  from public.generated_question_candidates
  where id = p_candidate_id
  for update;

  if not found then
    raise exception 'Generated question candidate % was not found.', p_candidate_id;
  end if;

  if v_candidate.review_status = 'Published' then
    return v_candidate.published_question_id;
  end if;

  if v_candidate.review_status <> 'Approved' then
    raise exception 'Candidate must be approved before publishing. Current review_status: %', v_candidate.review_status;
  end if;

  if v_candidate.reviewed_by is null or v_candidate.reviewed_at is null then
    raise exception 'Candidate requires one recorded admin or owner approval before publishing.';
  end if;

  if v_candidate.validation_status <> 'Valid' then
    raise exception 'Candidate must be valid before publishing. Current validation_status: %', v_candidate.validation_status;
  end if;

  if v_candidate.question_hash is not null and exists (
    select 1 from public.questions q where q.question_hash = v_candidate.question_hash
  ) then
    raise exception 'A live question with this question_hash already exists.';
  end if;

  select value
  into v_partition_key
  from jsonb_array_elements_text(v_candidate.partition_keys)
  limit 1;

  v_partition_key := coalesce(nullif(v_partition_key, ''), nullif(v_candidate.category, ''), 'Business Administration Core');

  insert into public.questions (
    partition_key,
    performance_indicator,
    question_type,
    question_text,
    options,
    correct_option_id,
    explanation,
    difficulty,
    tags,
    lifecycle_state,
    question_hash
  )
  values (
    v_partition_key,
    v_candidate.performance_indicator,
    v_candidate.question_type,
    v_candidate.question_text,
    v_candidate.options,
    v_candidate.correct_option_id,
    v_candidate.explanation,
    v_candidate.difficulty,
    v_candidate.tags,
    'Active',
    v_candidate.question_hash
  )
  returning id into v_published_question_id;

  update public.generated_question_candidates
  set review_status = 'Published',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      published_question_id = v_published_question_id
  where id = p_candidate_id;

  return v_published_question_id;
end;

declare
  matched_value text;
begin
  if nullif(trim(new.display_name), '') is null then
    return new;
  end if;

  select term into matched_value
  from public.banned_terms
  where active
    and lower(new.display_name) like '%' || lower(term) || '%'
  order by length(term) desc
  limit 1;

  if matched_value is not null then
    insert into public.name_reviews (
      user_id,
      submitted_name,
      matched_term,
      status
    )
    select new.user_id, new.display_name, matched_value, 'Pending'
    where not exists (
      select 1
      from public.name_reviews
      where user_id = new.user_id
        and submitted_name = new.display_name
        and status = 'Pending'
    );
  end if;

  return new;
end;

declare
  actor_id uuid := auth.uid();
  legacy_row public.test_ids%rowtype;
  normalized_status text := initcap(lower(btrim(coalesce(p_resolution_status, ''))));
  normalized_replacement text := nullif(upper(btrim(coalesce(p_replacement_test_id, ''))), '');
  clean_reason text := btrim(coalesce(p_reason, ''));
begin
  if not public.is_admin() or actor_id is null then
    raise exception 'Administrator or Owner access is required to resolve legacy Test IDs.';
  end if;

  if normalized_status not in ('Replaced', 'Retired') then
    raise exception 'Legacy resolution must be Replaced or Retired.';
  end if;

  if length(clean_reason) < 10 then
    raise exception 'A resolution reason of at least 10 characters is required.';
  end if;

  select *
  into legacy_row
  from public.test_ids
  where id = upper(btrim(p_legacy_test_id))
  for update;

  if not found then
    raise exception 'Legacy Test ID was not found.';
  end if;

  if legacy_row.generation_status <> 'Legacy' then
    raise exception 'Only unresolved Legacy Test IDs can use this workflow.';
  end if;

  if normalized_status = 'Replaced' then
    if normalized_replacement is null or normalized_replacement = legacy_row.id then
      raise exception 'A different replacement Test ID is required.';
    end if;

    if not exists (
      select 1
      from public.test_ids replacement
      where replacement.id = normalized_replacement
        and replacement.generation_status = 'Ready'
        and replacement.selected_question_count = replacement.question_count
    ) then
      raise exception 'Replacement Test ID must be a complete Ready definition.';
    end if;
  elsif normalized_replacement is not null then
    raise exception 'Retired legacy Test IDs cannot specify a replacement.';
  end if;

  update public.test_ids
  set generation_status = 'Retired',
      retired_at = now(),
      content_policy = 'current_with_warning',
      generation_metadata = generation_metadata || jsonb_build_object(
        'legacy_resolution', normalized_status,
        'legacy_resolved_at', now(),
        'legacy_resolved_by', actor_id
      )
  where definition_id = legacy_row.definition_id;

  insert into public.legacy_test_id_resolutions (
    legacy_test_id,
    resolution_status,
    replacement_test_id,
    reason,
    resolved_by
  )
  values (
    legacy_row.id,
    normalized_status,
    normalized_replacement,
    clean_reason,
    actor_id
  );

  insert into public.admin_audit_logs (
    actor_user_id,
    actor_email,
    action,
    resource_type,
    resource_id,
    reason,
    metadata
  )
  values (
    actor_id,
    (select email from auth.users where id = actor_id),
    'Legacy Test ID ' || lower(normalized_status),
    'test_id',
    legacy_row.id,
    clean_reason,
    jsonb_build_object('replacement_test_id', normalized_replacement)
  );
end;

declare
  actor_id uuid := auth.uid();
  actor_role text := public.current_user_role();
  report_row public.question_reports%rowtype;
  question_row public.questions%rowtype;
  event_id uuid;
  clean_state text := trim(coalesce(p_new_lifecycle_state, ''));
  clean_reason text := trim(coalesce(p_reason, ''));
  clean_message text := trim(coalesce(p_resolution_message, ''));
  clean_key text := trim(coalesce(p_idempotency_key, ''));
begin
  if not public.is_admin() or actor_id is null then raise exception 'Administrator or Owner access is required.'; end if;
  if clean_state not in ('Active','Retired') then raise exception 'Invalid lifecycle state.'; end if;
  if length(clean_reason) < 5 or length(clean_reason) > 1000 then raise exception 'Lifecycle reason must contain between 5 and 1000 characters.'; end if;
  if length(clean_message) < 5 or length(clean_message) > 1000 then raise exception 'A public resolution message is required.'; end if;
  if length(clean_key) < 1 or length(clean_key) > 128 then raise exception 'A valid idempotency key is required.'; end if;

  select report.* into report_row from public.question_reports report
  where report.id = p_report_id for update;
  if not found then raise exception 'Question report was not found.'; end if;
  if report_row.status in ('resolved','rejected','duplicate') then
    if report_row.status = 'resolved' and report_row.resolution_idempotency_key = clean_key
      and report_row.lifecycle_event_id is not null then
      select * into question_row from public.questions where id = report_row.question_id;
      return query select report_row.id, report_row.status, report_row.version,
        question_row.id, question_row.lifecycle_state, question_row.updated_at,
        report_row.lifecycle_event_id;
      return;
    end if;
    raise exception 'Finalized reports cannot be changed.';
  end if;
  if report_row.version <> p_expected_report_version then raise exception 'Report version conflict. Reload before retrying.'; end if;

  select question.* into question_row from public.questions question
  where question.id = report_row.question_id for update;
  if not found then raise exception 'Reported question was not found.'; end if;
  if question_row.updated_at <> p_expected_question_updated_at then raise exception 'Question version conflict. Reload before retrying.'; end if;
  if question_row.lifecycle_state = clean_state then raise exception 'Question is already in the requested lifecycle state.'; end if;

  insert into public.question_lifecycle_events(
    question_id, previous_state, new_state, actor_user_id, reason
  ) values (
    question_row.id, question_row.lifecycle_state, clean_state, actor_id, clean_reason
  ) returning id into event_id;

  update public.questions set lifecycle_state = clean_state
  where id = question_row.id returning * into question_row;

  update public.question_reports
  set status = 'resolved',
      resolution_category = case when clean_state = 'Retired' then 'retired' else 'restored' end,
      resolution_message = clean_message, resolved_at = now(), reviewed_by = actor_id,
      reviewed_at = now(), lifecycle_event_id = event_id,
      resolution_idempotency_key = clean_key, version = version + 1
  where id = report_row.id returning * into report_row;

  insert into public.admin_audit_logs(
    actor_user_id, actor_email, actor_role, action, resource_type, resource_id,
    report_id, reason, correlation_id, previous_values, new_values, metadata
  ) values (
    actor_id, (select email from auth.users where id = actor_id), actor_role,
    case when clean_state = 'Retired' then 'question.retired' else 'question.restored' end,
    'question', question_row.id::text, report_row.id, clean_reason, clean_key,
    jsonb_build_object('lifecycle_state', case when clean_state = 'Retired' then 'Active' else 'Retired' end),
    jsonb_build_object('lifecycle_state', clean_state),
    jsonb_build_object('lifecycle_event_id', event_id)
  );

  return query select report_row.id, report_row.status, report_row.version,
    question_row.id, question_row.lifecycle_state, question_row.updated_at, event_id;
end;

declare
  actor_id uuid := auth.uid();
